// corpusDir is the committed synthetic replay sequence generated by
// scripts/fixtures/gen-synthetic-replay.sh: 24 frames at 10 fps that walk an
// empty scene, a textbox appearing, a typewriter reveal, a held line, an instant
// second page and a dismissal (docs/spec/11 "Fixture origins" item 3).

func corpusDir(t *testing.T) string {
	t.Helper()
	d := filepath.Join("..", "..", "..", "testdata", "synthetic", "replay", "dialogue-advance-001")
	if _, err := os.Stat(filepath.Join(d, "timestamps.json")); err != nil {
		t.Skipf("NOT RUN: synthetic replay corpus missing (%v); run scripts/fixtures/gen-synthetic-replay.sh", err)
	}
	abs, err := filepath.Abs(d)
	if err != nil {
		t.Fatalf("abs: %v", err)
	}
	return abs
}

// --- the committed corpus itself -------------------------------------------

type normRect struct {
	X, Y, W, H float64
}

type truthRow struct {
	File    string   `json:"file"`
	TsNS    int64    `json:"ts_ns"`
	Present bool     `json:"box_present"`
	Alpha   float64  `json:"box_alpha"`
	Text    string   `json:"text"`
	Full    bool     `json:"text_is_full_line"`
	Line    string   `json:"line"`
	Variant string   `json:"variant"`
	Origin  string   `json:"origin"`
	Rect    normRect `json:"rect"` // OCR region: the box minus its decorative border
	Box     normRect `json:"box"`  // where the textbox was drawn
	Size    struct {
		W int `json:"w"`
		H int `json:"h"`
	} `json:"size"`
}

func readTruth(t *testing.T) []truthRow {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(corpusDir(t), "truth.json"))
	if err != nil {
		t.Fatalf("truth.json: %v", err)
	}
	var rows []truthRow
	if err := json.Unmarshal(raw, &rows); err != nil {
		t.Fatalf("parse truth.json: %v", err)
	}
	return rows
}

func TestCorpusProvenanceAndShape(t *testing.T) {
	// Before behaviour: does the fixture describe itself honestly? Every frame on
	// disk has a manifest row and a truth row, the cadence is exactly 10 fps, and
	// each row carries the provenance label AGENTS.md rule 5 requires. A fixture
	// without a recorded origin is the thing docs/spec/12 forbids.
	rows := readTruth(t)
	entries, err := (&Source{Dir: corpusDir(t)}).Manifest()
	if err != nil {
		t.Fatalf("Manifest: %v", err)
	}
	if len(entries) != 24 {
		t.Errorf("timestamps.json has %d rows, want the 24 the generator emits", len(entries))
	}
	if len(rows) != len(entries) {
		t.Fatalf("truth.json has %d rows vs %d manifest rows", len(rows), len(entries))
	}
	pngs, _ := filepath.Glob(filepath.Join(corpusDir(t), "*.png"))
	if len(pngs) != len(entries) {
		t.Errorf("%d PNGs on disk vs %d manifest rows: an unlabelled frame in a ground-truth directory is forbidden", len(pngs), len(entries))
	}
	variants := map[string]int{}
	var total, largest int64
	for i, r := range rows {
		e := entries[i]
		if r.File != e.File {
			t.Fatalf("row %d: truth says %s, manifest says %s", i, r.File, e.File)
		}
		if r.TsNS != e.TsNS || r.TsNS != int64((i+1)*100_000_000) {
			t.Fatalf("row %d: ts_ns %d is not the exact 100 ms step %d", i, r.TsNS, (i+1)*100_000_000)
		}
		if r.Origin != "generated_synthetic" {
			t.Errorf("row %d origin = %q: generated content must say so", i, r.Origin)
		}
		if r.Size.W != 640 || r.Size.H != 480 {
			t.Errorf("row %d size = %dx%d, want 640x480", i, r.Size.W, r.Size.H)
		}
		if _, err := os.Stat(filepath.Join(corpusDir(t), r.File)); err != nil {
			t.Fatalf("manifest names %s which is not on disk: %v", r.File, err)
		}
		fi, err := os.Stat(filepath.Join(corpusDir(t), r.File))
		if err == nil {
			total += fi.Size()
			if fi.Size() > largest {
				largest = fi.Size()
			}
		}
		variants[r.Variant]++
	}
	for _, want := range []struct {
		name string
		n    int
	}{
		{"empty_scene", 3}, {"box_appearing", 2}, {"revealing", 8},
		{"stable", 5}, {"page_two", 4}, {"box_dismissed", 2},
	} {
		if variants[want.name] != want.n {
			t.Errorf("corpus has %d %q frames, want %d: the dialogue-advance scenario is defined by this shape", variants[want.name], want.name, want.n)
		}
	}
	if largest > 40_000 {
		t.Errorf("largest frame is %d bytes; the corpus budget is 40 KB per frame", largest)
	}
	t.Logf("corpus: 24 frames, %.1f KB total, largest %.1f KB, stages %v", float64(total)/1024, float64(largest)/1024, variants)
}

func TestTruthDescribesItsOwnPixels(t *testing.T) {
	// The anti-theatre check: box presence is re-derived from the pixels rather
	// than trusted from truth.json, so a generator change that desynchronised the
	// labels from the images fails here instead of corrupting every downstream
	// expectation.
	for _, r := range readTruth(t) {
		img := openCorpusPNG(t, r.File)
		dark := darkFraction(img, r.Rect)
		present := dark > 0.30
		if present != r.Present {
			t.Errorf("%s: truth says box_present=%v but %.1f%% of the region is dark", r.File, r.Present, dark*100)
		}
		if !r.Present && r.Text != "" {
			t.Errorf("%s: truth records text %q with no box: text with no textbox is a different fixture", r.File, r.Text)
		}
		if r.Present && r.Alpha == 0 {
			t.Errorf("%s: box_present with alpha 0", r.File)
		}
		if r.Full && r.Text == "" {
			t.Errorf("%s: claims a complete line with no text", r.File)
		}
	}
}

// --- replay behaviour -------------------------------------------------------

func TestReplaysCorpusInOrderWithRecordedTimestamps(t *testing.T) {
	s := &Source{Dir: corpusDir(t), Speed: 0, Sleeper: noopSleep}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch, err := s.Start(ctx)
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer s.Close()

	rows := readTruth(t)
	frames := drainAll(t, ch, 30*time.Second)
	if len(frames) != len(rows) {
		t.Fatalf("delivered %d frames, want %d", len(frames), len(rows))
	}
	var prev int64
	for i, f := range frames {
		if err := f.Validate(); err != nil {
			t.Fatalf("frame %d invalid: %v", i, err)
		}
		// The replayed timeline is the recorded one — this is the single most
		// important assertion in the file, because a replay that re-stamped
		// frames with the wall clock would let every timing-sensitive test in
		// the pipeline pass while testing nothing (docs/spec/01 invariant 1).
		if want := rows[i].TsNS; f.CaptureTimestampNS != want {
			t.Fatalf("frame %d capture_timestamp_ns = %d, want the recorded %d", i, f.CaptureTimestampNS, want)
		}
		if i > 0 && f.CaptureTimestampNS <= prev {
			t.Fatalf("frame %d timestamp %d did not advance past %d", i, f.CaptureTimestampNS, prev)
		}
		prev = f.CaptureTimestampNS
		if f.SourceClock != capture.ClockReplay {
			t.Fatalf("frame %d clock = %q, want %q", i, f.SourceClock, capture.ClockReplay)
		}
		if f.Seq != int64(i+1) {
			t.Fatalf("frame %d seq = %d, want %d", i, f.Seq, i+1)
		}
		if f.Width != 640 || f.Height != 480 {
			t.Fatalf("frame %d size = %dx%d, want 640x480", i, f.Width, f.Height)
		}
		if f.PixFmt != capture.PixPNG {
			t.Errorf("frame %d format = %q, want png", i, f.PixFmt)
		}
		if f.Dropped != 0 {
			t.Errorf("frame %d reports %d dropped: replay is lossless by contract", i, f.Dropped)
		}
	}
	if st := s.Stats(); st.Delivered != 24 || st.DecodeErrors != 0 {
		t.Errorf("stats after full replay: %+v", st)
	}
	// End-of-stream is the channel closing: consumers must be able to tell
	// "the recording ended" from "I am still waiting".
	if _, open := <-ch; open {
		t.Error("channel still open after the last frame")
	}
	if st := s.Stats(); st.State == capture.StateRunning {
		t.Error("state still running after end-of-stream")
	}
}

func TestRepeatedIdenticalFramesAreDelivered(t *testing.T) {
	// docs/spec/12 "Visual perception" lists "repeated identical frames" as a
	// case, and docs/spec/05 says a typewriter prefix is not a new utterance —
	// both are only testable if the source delivers the duplicates rather than
	// coalescing them. Five held frames must arrive as five frames with one hash.
	s := &Source{Dir: corpusDir(t), Speed: 0, Sleeper: noopSleep}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch, _ := s.Start(ctx)
	defer s.Close()
	frames := drainAll(t, ch, 30*time.Second)
	if len(frames) != 24 {
		t.Fatalf("got %d frames", len(frames))
	}

	// Frames 14..18 (1-based) are the held line.
	held := map[string]int{}
	for _, f := range frames[13:18] {
		held[f.Hash]++
	}
	if len(held) != 1 {
		t.Errorf("the 5 held frames produced %d distinct hashes; the corpus must be pixel-stable for expectations to mean anything", len(held))
	}
	if total := sumMap(held); total != 5 {
		t.Errorf("only %d of the 5 held frames arrived", total)
	}
	// The typewriter's 8 reveal frames must be 8 distinct pictures.
	reveal := map[string]bool{}
	for _, f := range frames[5:13] {
		reveal[f.Hash] = true
	}
	if len(reveal) != 8 {
		t.Errorf("the 8 reveal frames produced %d distinct hashes: a partial reveal that hashes identically would leave the tracker stuck in REVEALING with no evidence", len(reveal))
	}
	// Page two differs from page one, and the dismissed scene is the opening scene.
	if frames[18].Hash == frames[13].Hash {
		t.Error("page two is pixel-identical to the held line")
	}
	if frames[0].Hash != frames[23].Hash {
		t.Error("the dismissed-box scene differs from the opening empty scene")
	}
	// Sequence numbers stay unique across duplicates: the tracker fences stale
	// work by frame number, not by pixels.
	if frames[13].Seq >= frames[14].Seq {
		t.Error("duplicate frames did not get increasing sequence numbers")
	}
}

func TestRealTimePacingFollowsTheRecording(t *testing.T) {
	// Pacing is asserted as a *schedule*, not as elapsed wall time: waiting two
	// seconds to prove two seconds of pacing would only prove the test slept.
	// This is ADR-0007's "never wall-clock sleeps" rule applied to this package.
	sl := &fakeSleeper{}
	s := &Source{Dir: corpusDir(t), Speed: 1.0, Sleeper: sl.sleep}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch, err := s.Start(ctx)
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer s.Close()

	frames := drainAll(t, ch, 30*time.Second)
	if len(frames) != 24 {
		t.Fatalf("delivered %d frames", len(frames))
	}
	log := sl.log()
	if len(log) != 23 {
		t.Fatalf("%d sleeps for 24 frames, want 23: nothing should be paced before the first frame", len(log))
	}
	for i, d := range log {
		if d != 100*time.Millisecond {
			t.Fatalf("sleep %d = %v, want exactly 100ms", i, d)
		}
	}
	if got := sl.total(); got != 2300*time.Millisecond {
		t.Errorf("total paced time = %v, want 2.3s for 24 frames at 10 fps", got)
	}
}

func TestSpeedScalesTheTimelineWithoutRewritingIt(t *testing.T) {
	for _, tc := range []struct {
		speed float64
		want  time.Duration
	}{
		{4.0, 575 * time.Millisecond},
		{2.0, 1150 * time.Millisecond},
		{0.5, 4600 * time.Millisecond},
	} {
		sl := &fakeSleeper{}
		s := &Source{Dir: corpusDir(t), Speed: tc.speed, Sleeper: sl.sleep}
		ctx, cancel := context.WithCancel(context.Background())
		ch, err := s.Start(ctx)
		if err != nil {
			t.Fatalf("Start: %v", err)
		}
		frames := drainAll(t, ch, 30*time.Second)
		cancel()
		s.Close()
		if len(frames) != 24 {
			t.Fatalf("speed %g: %d frames", tc.speed, len(frames))
		}
		if got := sl.total(); got != tc.want {
			t.Errorf("speed %g: paced %v, want %v", tc.speed, got, tc.want)
		}
		// Wall-clock speed changes; the frame's own clock never does. A fast
		// replay must not look to the tracker like a game running fast.
		if frames[0].CaptureTimestampNS != 100_000_000 || frames[23].CaptureTimestampNS != 2_400_000_000 {
			t.Errorf("speed %g: timestamps changed (%d .. %d)", tc.speed, frames[0].CaptureTimestampNS, frames[23].CaptureTimestampNS)
		}
	}
}

func TestSpeedZeroNeverSleeps(t *testing.T) {
	// The claim that makes fixture replay the gate that runs on every PR:
	// thousands of frames in milliseconds. If anything sleeps at speed 0 the
	// reasoning is false. The assertion is the injected sleeper's call count,
	// not wall time: a bound on elapsed time would be a test of this machine's
	// PNG decoder under load, not of the pacing, and it was exactly that
	// flake that made this test fail under parallel CI load.
	var calls atomic.Int64
	s := &Source{Dir: corpusDir(t), Speed: 0, Sleeper: func(ctx context.Context, _ time.Duration) error {
		calls.Add(1)
		return nil
	}}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch, _ := s.Start(ctx)
	defer s.Close()
	frames := drainAll(t, ch, 10*time.Second)
	if len(frames) != 24 {
		t.Fatalf("%d frames", len(frames))
	}
	if got := calls.Load(); got != 0 {
		t.Errorf("Sleeper called %d times at speed 0, want 0", got)
	}
}

func TestLoopKeepsTimestampsAndSequenceMonotonic(t *testing.T) {
	// A looping replay stands in for "the game is idling here" during a long
	// test, so it must never present time going backwards: invariant 1 has no
	// exception for a loop, and a tracker that saw the clock step back would
	// reset its stability window for a reason that has nothing to do with the
	// game.
	s := &Source{Dir: corpusDir(t), Speed: 1.0, Loop: true, Sleeper: (&fakeSleeper{}).sleep}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch, err := s.Start(ctx)
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer s.Close()

	var frames []capture.Frame
	for len(frames) < 50 {
		select {
		case f, ok := <-ch:
			if !ok {
				t.Fatalf("looping source closed its channel after %d frames", len(frames))
			}
			frames = append(frames, f)
		case <-time.After(10 * time.Second):
			t.Fatalf("only %d frames from a looping source", len(frames))
		}
	}
	for i, f := range frames {
		if f.Seq != int64(i+1) {
			t.Fatalf("frame %d seq = %d: a loop must not restart the sequence", i, f.Seq)
		}
		if i > 0 {
			d := f.CaptureTimestampNS - frames[i-1].CaptureTimestampNS
			if d != 100_000_000 {
				t.Fatalf("frame %d inter-frame step = %d ns, want a constant 100ms across the wrap", i, d)
			}
		}
	}
	// The second pass replays the same pixels, one stride later.
	if frames[0].Hash != frames[24].Hash {
		t.Error("the loop's second pass did not replay the same pixels")
	}
	if got := frames[24].CaptureTimestampNS - frames[0].CaptureTimestampNS; got != 2400_000_000 {
		t.Errorf("loop offset = %d ns, want 2.4s (24 frames at the recorded cadence)", got)
	}
}

func TestCancellationEndsTheStreamPromptly(t *testing.T) {
	// Real sleeper, cancelled mid-sequence: the capture loop's shutdown deadline
	// depends on this (docs/spec/01 "deadline/cancellation propagation").
	s := &Source{Dir: corpusDir(t), Speed: 1.0} // nil Sleeper = real time
	ctx, cancel := context.WithCancel(context.Background())
	ch, err := s.Start(ctx)
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	if _, ok := <-ch; !ok {
		t.Fatal("no first frame")
	}
	start := time.Now()
	cancel()
	for range ch { // must terminate
	}
	if err := s.Close(); err != nil {
		t.Errorf("Close after cancel: %v", err)
	}
	if d := time.Since(start); d > 2*time.Second {
		t.Errorf("cancelled replay took %v to end; it must not wait out the pacing", d)
	}
}

func TestCloseIsIdempotentAndSafeBeforeStart(t *testing.T) {
	s := &Source{Dir: corpusDir(t)}
	for i := 0; i < 3; i++ {
		if err := s.Close(); err != nil {
			t.Fatalf("Close #%d: %v", i, err)
		}
	}
	if st := s.Stats(); st.State != capture.StateStopped {
		t.Errorf("state after Close = %s, want stopped", st.State)
	}
}

func TestSecondStartRejected(t *testing.T) {
	s := &Source{Dir: corpusDir(t), Speed: 0, Sleeper: noopSleep}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if _, err := s.Start(ctx); err != nil {
		t.Fatalf("first Start: %v", err)
	}
	defer s.Close()
	if _, err := s.Start(ctx); !errors.Is(err, ErrAlreadyStarted) {
		t.Errorf("second Start = %v, want ErrAlreadyStarted", err)
	}
}

// --- manifest and provenance failures --------------------------------------

func TestManifestErrorsAreActionable(t *testing.T) {
	dir := t.TempDir()
	cases := []struct {
		name    string
		file    string
		body    string
		want    string
		wantErr error
	}{
		{"empty list", "empty.json", "[]", "no frames", ErrNoFrames},
		{"malformed json", "bad.json", "[{file:", "parse manifest", nil},
		{"zero timestamp", "zero.json", `[{"file":"a.png","ts_ns":0}]`, "ts_ns", nil},
		{"negative timestamp", "neg.json", `[{"file":"a.png","ts_ns":-5}]`, "ts_ns", nil},
		{"missing file name", "noname.json", `[{"ts_ns":5}]`, "unsafe file", nil},
		{"path traversal", "trav.json", `[{"file":"../../../../etc/passwd","ts_ns":1}]`, "unsafe file", nil},
		{"nested traversal", "trav2.json", `[{"file":"a/../../b.png","ts_ns":1}]`, "unsafe file", nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			path := filepath.Join(dir, tc.file)
			if err := os.WriteFile(path, []byte(tc.body), 0o644); err != nil {
				t.Fatalf("write: %v", err)
			}
			s := &Source{Dir: dir, TimestampsFile: path}
			_, err := s.Start(context.Background())
			if err == nil {
				t.Fatal("Start accepted a broken manifest")
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Errorf("error %q does not mention %q", err, tc.want)
			}
			if tc.wantErr != nil && !errors.Is(err, tc.wantErr) {
				t.Errorf("error %q is not %v", err, tc.wantErr)
			}
			// A fault must be reportable, not merely fatal (docs/spec/13).
			if st := s.Stats(); st.State != capture.StateFailed {
				t.Errorf("state = %s after a manifest failure, want failed", st.State)
			}
		})
	}
	t.Run("missing manifest", func(t *testing.T) {
		s := &Source{Dir: dir, TimestampsFile: filepath.Join(dir, "nope.json")}
		if _, err := s.Start(context.Background()); err == nil || !strings.Contains(err.Error(), "read manifest") {
			t.Errorf("Start error = %v", err)
		}
	})
	if _, err := (&Source{}).Start(context.Background()); err == nil {
		t.Error("Start with no Dir succeeded")
	}
}

func TestMissingFrameFileEndsTheStreamAsFailed(t *testing.T) {
	// A recording whose file vanished must not quietly deliver a shorter
	// sequence: the value of fixture replay is that the timeline is the one that
	// was recorded. The stream must end, and say why.
	dir := t.TempDir()
	if err := writeSolidPNG(filepath.Join(dir, "f.png"), color.RGBA{1, 2, 3, 255}); err != nil {
		t.Fatalf("write frame: %v", err)
	}
	manifest := fmt.Sprintf(`[{"file":"f.png","ts_ns":%d},{"file":"gone.png","ts_ns":%d},{"file":"f.png","ts_ns":%d}]`,
		100_000_000, 200_000_000, 300_000_000)
	if err := os.WriteFile(filepath.Join(dir, "timestamps.json"), []byte(manifest), 0o644); err != nil {
		t.Fatalf("manifest: %v", err)
	}
	s := &Source{Dir: dir, Speed: 0, Sleeper: noopSleep}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch, err := s.Start(ctx)
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer s.Close()
	var got []capture.Frame
	for f := range ch {
		got = append(got, f)
	}
	if len(got) != 1 {
		t.Fatalf("delivered %d frames before failing, want 1", len(got))
	}
	st := s.Stats()
	if st.State != capture.StateFailed {
		t.Errorf("state = %s, want failed", st.State)
	}
	if !strings.Contains(st.LastError, "gone.png") {
		t.Errorf("LastError %q does not name the missing file", st.LastError)
	}
}

func TestDecodeReportsWhatItActuallyRead(t *testing.T) {
	// decode() claims the reported format comes from the decoder that ran rather
	// than the file extension. A PNG with a .jpg name is the corruption case that
	// claim exists to catch.
	dir := t.TempDir()
	img := image.NewRGBA(image.Rect(0, 0, 16, 16))
	for y := 0; y < 16; y++ {
		for x := 0; x < 16; x++ {
			img.Set(x, y, color.RGBA{uint8(x * 16), uint8(y * 16), 40, 255})
		}
	}
	f, err := os.Create(filepath.Join(dir, "frame.jpg"))
	if err != nil {
		t.Fatalf("create: %v", err)
	}
	if err := png.Encode(f, img); err != nil {
		f.Close()
		t.Fatalf("encode: %v", err)
	}
	f.Close()
	if err := os.WriteFile(filepath.Join(dir, "timestamps.json"),
		[]byte(`[{"file":"frame.jpg","ts_ns":100000000}]`), 0o644); err != nil {
		t.Fatalf("manifest: %v", err)
	}
	s := &Source{Dir: dir, Speed: 0, Sleeper: noopSleep}
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	ch, err := s.Start(ctx)
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	defer s.Close()
	frames := drainAll(t, ch, 10*time.Second)
	if len(frames) != 1 {
		t.Fatalf("%d frames", len(frames))
	}
	if frames[0].PixFmt != capture.PixPNG {
		t.Errorf("format = %q; the .jpg file holds PNG bytes and the source must report what it decoded", frames[0].PixFmt)
	}
	if frames[0].Width != 16 || frames[0].Height != 16 {
		t.Errorf("size = %dx%d, want 16x16", frames[0].Width, frames[0].Height)
	}
}

func TestIDNamesTheCorpus(t *testing.T) {
	if got := (&Source{Dir: corpusDir(t)}).ID(); got != "replay:dialogue-advance-001" {
		t.Errorf("ID = %q", got)
	}
	if got := (&Source{}).ID(); !strings.Contains(got, "no directory") {
		t.Errorf("empty Dir ID = %q; it should say so", got)
	}
}

// --- generator determinism --------------------------------------------------

// TestGeneratorReproducesCorpus guards the property the whole corpus rests on:
// rerunning scripts/fixtures/gen-synthetic-replay.sh reproduces byte-identical
// frames. The milestone gate does the same check with sha256sum; this keeps the
// claim inside `go test` so it cannot rot silently between gates. A generator
// that drifts makes every frame hash in every recorded expectation wrong, and a
// failing test could not tell "the pipeline changed" from "the generator
// changed".
func TestGeneratorReproducesCorpus(t *testing.T) {
	script, err := filepath.Abs(filepath.Join("..", "..", "..", "scripts", "fixtures", "gen-synthetic-replay.sh"))
	if err != nil {
		t.Fatalf("abs: %v", err)
	}
	if _, err := os.Stat(script); err != nil {
		t.Skipf("NOT RUN: generator not reachable (%v)", err)
	}
	if _, err := exec.LookPath("magick"); err != nil {
		t.Skipf("NOT RUN: ImageMagick absent (%v); the generator needs it", err)
	}
	before := hashCorpus(t, corpusDir(t))
	out := filepath.Join(t.TempDir(), "regen")
	cmd := exec.Command("bash", script, out)
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("regenerate: %v", err)
	}
	after := hashCorpus(t, out)
	if before != after {
		t.Errorf("regenerated corpus differs from the committed one (%s != %s): the generator is not deterministic", before[:16], after[:16])
	} else {
		t.Logf("generator is byte-reproducible (corpus digest %s)", before[:16])
	}
}

// --- helpers ----------------------------------------------------------------

// fakeSleeper replaces the pacing so the schedule can be asserted rather than
// waited out.
type fakeSleeper struct {
	mu   sync.Mutex
	durs []time.Duration
	prog time.Duration
}

func (f *fakeSleeper) sleep(ctx context.Context, d time.Duration) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	default:
	}
	f.mu.Lock()
	f.durs = append(f.durs, d)
	f.prog += d
	f.mu.Unlock()
	return nil
}

func (f *fakeSleeper) total() time.Duration {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.prog
}

func (f *fakeSleeper) log() []time.Duration {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]time.Duration(nil), f.durs...)
}

func noopSleep(ctx context.Context, _ time.Duration) error { return ctx.Err() }

func sumMap(m map[string]int) int {
	n := 0
	for _, v := range m {
		n += v
	}
	return n
}

func openCorpusPNG(t *testing.T, name string) *image.RGBA {
	t.Helper()
	f, err := os.Open(filepath.Join(corpusDir(t), name))
	if err != nil {
		t.Fatalf("open %s: %v", name, err)
	}
	defer f.Close()
	img, err := png.Decode(f)
	if err != nil {
		t.Fatalf("decode %s: %v", name, err)
	}
	// The corpus is paletted (a 20-colour synthetic frame), so it is expanded
	// here the way the source expands it; asserting against the raw decode would
	// be testing image/png rather than the fixture.
	rgba := image.NewRGBA(img.Bounds())
	draw.Draw(rgba, rgba.Bounds(), img, img.Bounds().Min, draw.Src)
	return rgba
}

// darkFraction measures the share of a normalised rect that is dark, which is how
// a textbox (a dark translucent panel) is distinguished from a scene.
func darkFraction(img *image.RGBA, r normRect) float64 {
	b := img.Bounds()
	x0 := b.Min.X + int(r.X*float64(b.Dx()))
	y0 := b.Min.Y + int(r.Y*float64(b.Dy()))
	x1 := b.Min.X + int((r.X+r.W)*float64(b.Dx()))
	y1 := b.Min.Y + int((r.Y+r.H)*float64(b.Dy()))
	if x1 <= x0 || y1 <= y0 {
		return 0
	}
	dark, total := 0, 0
	for y := y0; y < y1; y++ {
		for x := x0; x < x1; x++ {
			i := img.PixOffset(x, y)
			luma := (int(img.Pix[i]) + int(img.Pix[i+1]) + int(img.Pix[i+2])) / 3
			if luma < 90 {
				dark++
			}
			total++
		}
	}
	if total == 0 {
		return 0
	}
	return float64(dark) / float64(total)
}

func writeSolidPNG(path string, c color.RGBA) error {
	img := image.NewRGBA(image.Rect(0, 0, 32, 32))
	for y := 0; y < 32; y++ {
		for x := 0; x < 32; x++ {
			img.Set(x, y, c)
		}
	}
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	return png.Encode(f, img)
}

func drainAll(t *testing.T, ch <-chan capture.Frame, within time.Duration) []capture.Frame {
	t.Helper()
	var out []capture.Frame
	deadline := time.NewTimer(within)
	defer deadline.Stop()
	for {
		select {
		case f, ok := <-ch:
			if !ok {
				return out
			}
			out = append(out, f)
		case <-deadline.C:
			t.Fatalf("timed out after %v with %d frames delivered", within, len(out))
		}
	}
}

func hashCorpus(t *testing.T, dir string) string {
	t.Helper()
	files, err := filepath.Glob(filepath.Join(dir, "*"))
	if err != nil || len(files) == 0 {
		t.Fatalf("glob %s: %v (%d files)", dir, err, len(files))
	}
	sort.Strings(files)
	h := sha256.New()
	for _, f := range files {
		fi, err := os.Stat(f)
		if err != nil || fi.IsDir() {
			continue
		}
		fmt.Fprintf(h, "%s\n", filepath.Base(f))
		b, err := os.ReadFile(f)
		if err != nil {
			t.Fatalf("read %s: %v", f, err)
		}
		h.Write(b)
	}
	return hex.EncodeToString(h.Sum(nil))
}
